package com.example.riskplatform.service.cache;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Service;import java.time.Duration;import java.util.concurrent.*;
@Service @ConditionalOnProperty(name="app.redis.enabled",havingValue="false",matchIfMissing=true)public class MemoryCacheService implements CacheService{private record V(String v,long e){}private final ConcurrentHashMap<String,V>m=new ConcurrentHashMap<>();public String get(String k){V x=m.get(k);if(x==null||x.e<System.currentTimeMillis()){m.remove(k);return null;}return x.v;}public void set(String k,String v,Duration t){m.put(k,new V(v,System.currentTimeMillis()+t.toMillis()));}}
